BASE_NEW={}
for row in NEW_DATA.splitlines():
    source,en,es,*values=row.split('|')
    if source.endswith(" "):values=[value if value.endswith(" ") or code=="ja" else value+" " for code,value in zip(CODES,values)]
    BASE_NEW[source]=(en,es)
    DATA+='\n'+source+'|'+'|'.join(values)

EXTRA={code:{} for code in CODES}
for row in DATA.splitlines():
    source,*values=row.split('|')
    if len(values)!=len(CODES):raise ValueError("Invalid translation row: "+source)
    for code,value in zip(CODES,values):EXTRA[code][source]=value
